function applyLanguage(){languageQueued=false;if(languageObserver)languageObserver.disconnect();document.documentElement.lang=uiLanguage==='zh'?'zh-CN':'en';document.title=translateUI('Optical Industry & Supply Chain Atlas');
 const walk=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walk.nextNode()){if(n.parentElement?.closest('script,style,[data-language-control]'))continue;let prev=languageOriginal.get(n);if(!prev||n.nodeValue!==prev.last)prev={original:n.nodeValue,last:n.nodeValue};const translated=translateUI(prev.original);if(n.parentElement?.tagName==='OPTION'&&!n.parentElement.hasAttribute('value'))n.parentElement.setAttribute('value',prev.original.trim());n.nodeValue=translated;prev.last=translated;languageOriginal.set(n,prev)}
 for(const el of document.querySelectorAll('[placeholder],[aria-label],[title]')){if(el.closest('[data-language-control]'))continue;let record=languageAttributes.get(el)||{};for(const key of ['placeholder','aria-label','title'])if(el.hasAttribute(key)){let raw=el.getAttribute(key),p=record[key];if(!p||raw!==p.last)p={original:raw,last:raw};p.last=translateUI(p.original);el.setAttribute(key,p.last);record[key]=p}languageAttributes.set(el,record)}
 $('lang-en').setAttribute('aria-pressed',uiLanguage==='en');$('lang-zh').setAttribute('aria-pressed',uiLanguage==='zh');$('language-note').hidden=uiLanguage!=='zh';if(languageObserver)languageObserver.observe(document.body,{subtree:true,childList:true,characterData:true});
}
